/**
 * Build-time loader and helpers for the "Will it run?" pages.
 *
 * Data: data/compat-snapshot.json, generated by scripts/build-will-it-run-data.mjs
 * from the same play-session rollup that drives the in-app compatibility badge.
 * Per-game verdicts (Great / Works / Unreliable / Broken) come from the app's
 * own rules; this file does not re-judge games, it only summarises them.
 *
 * Server-only: uses `fs`. Import only from server components, generateStaticParams,
 * generateMetadata, sitemap.ts and robots.ts.
 */
import fs from 'node:fs'
import path from 'node:path'

/* ──────────────────────────────────────────────────────────────────────────
 * TUNABLE THRESHOLDS
 * ────────────────────────────────────────────────────────────────────────── */

/** Devices / GPUs need at least this many judged games to get their own page. */
export const MIN_GAMES_FOR_PAGE = 20

/** Summary band from the share of judged games rated Great or Works. */
export const BAND_MOSTLY_RUNS_MIN_SHARE = 0.75 // >= this: "Most tested games run"
export const BAND_MIXED_MIN_SHARE = 0.5 //        >= this (and below the above): "Mixed"
//                                                 below this: "Most tested games do not run reliably"

/* ──────────────────────────────────────────────────────────────────────────
 * Types (shape of data/compat-snapshot.json)
 * ────────────────────────────────────────────────────────────────────────── */

/** Number of GAMES in each verdict state. */
export interface States {
  great: number
  works: number
  unreliable: number
  broken: number
}
export type StateCode = 'G' | 'W' | 'U' | 'B'
/** [gameIndex, state, sessions, playableSessions, medianFps] */
export type GameRow = [number, StateCode, number, number, number | null]

export interface Entity {
  slug: string
  name: string
  kind: 'device' | 'gpu'
  vendor: string
  rawNames: string[]
  sessions: number
  playable: number
  gamesJudged: number
  states: States
  lastSeen: string
  games: GameRow[]
  failing: GameRow[]
  /** One char per meta.popular entry: G/W/U/B, or '-' = not enough data on this entity. */
  popular: string
  gpu?: string
  gpuSlug?: string
  gpuMix?: { gpu: string; share: number }[]
  deviceCount?: number
  topDevices?: { slug: string; name: string; sessions: number }[]
}

export interface VendorStats {
  vendor: string
  devices: number
  sessions: number
  playable: number
  states: States
}

export interface Snapshot {
  meta: {
    generatedAt: string
    dataThrough: string
    windowDays: number
    popular: number[]
    totals: { devices: number; gpus: number; sessions: number; gamesWithData: number }
    vendors: VendorStats[]
  }
  games: { id: number; name: string; slug: string }[]
  devices: Entity[]
  gpus: Entity[]
}

/* ──────────────────────────────────────────────────────────────────────────
 * Loader: fails the build if the snapshot is missing.
 * ────────────────────────────────────────────────────────────────────────── */

const SNAPSHOT_PATH = path.join(process.cwd(), 'data', 'compat-snapshot.json')
let cached: Snapshot | null = null

export function getSnapshot(): Snapshot {
  if (cached) return cached
  if (!fs.existsSync(SNAPSHOT_PATH)) {
    throw new Error(
      'data/compat-snapshot.json is missing. Generate it with scripts/build-will-it-run-data.mjs before building.',
    )
  }
  cached = JSON.parse(fs.readFileSync(SNAPSHOT_PATH, 'utf8')) as Snapshot
  return cached
}

/* ──────────────────────────────────────────────────────────────────────────
 * Lookups
 * ────────────────────────────────────────────────────────────────────────── */

export function hasPage(e: Entity): boolean {
  if (e.gamesJudged < MIN_GAMES_FOR_PAGE) return false
  if (e.kind === 'device' && e.slug === 'gpu') return false // would collide with /will-it-run/gpu/
  return true
}

let pagedDevices: Entity[] | null = null
let pagedGpus: Entity[] | null = null
let deviceBySlug: Map<string, Entity> | null = null
let gpuBySlug: Map<string, Entity> | null = null

export function getPagedDevices(): Entity[] {
  return (pagedDevices ??= getSnapshot().devices.filter(hasPage))
}
export function getPagedGpus(): Entity[] {
  return (pagedGpus ??= getSnapshot().gpus.filter(hasPage))
}
export function getDevice(slug: string): Entity | undefined {
  deviceBySlug ??= new Map(getPagedDevices().map((d) => [d.slug, d]))
  return deviceBySlug.get(slug)
}
export function getGpu(slug: string): Entity | undefined {
  gpuBySlug ??= new Map(getPagedGpus().map((g) => [g.slug, g]))
  return gpuBySlug.get(slug)
}

export function entityPath(e: { kind: 'device' | 'gpu'; slug: string }): string {
  return e.kind === 'gpu' ? `/will-it-run/gpu/${e.slug}/` : `/will-it-run/${e.slug}/`
}
export function gpuPathIfExists(slug: string | undefined): string | null {
  return slug && getGpu(slug) ? `/will-it-run/gpu/${slug}/` : null
}
export function devicePathIfExists(slug: string | null | undefined): string | null {
  return slug && getDevice(slug) ? `/will-it-run/${slug}/` : null
}

export function gameName(index: number): string {
  return getSnapshot().games[index]?.name ?? `Game ${index}`
}

/* ──────────────────────────────────────────────────────────────────────────
 * Verdict states (the app's own per-game verdicts)
 * ────────────────────────────────────────────────────────────────────────── */

export const STATE_LABELS: Record<StateCode, string> = {
  G: 'Great',
  W: 'Works',
  U: 'Unreliable',
  B: 'Broken',
}

/* ──────────────────────────────────────────────────────────────────────────
 * SUMMARY BAND for a device / GPU / vendor
 *
 * Share = games rated Great or Works / games judged (games with >= 5 sessions).
 *   >= BAND_MOSTLY_RUNS_MIN_SHARE -> 'runs'
 *   >= BAND_MIXED_MIN_SHARE       -> 'mixed'
 *   otherwise                     -> 'poor'
 * ────────────────────────────────────────────────────────────────────────── */

export type Band = 'runs' | 'mixed' | 'poor'

export const BAND_LABELS: Record<Band, string> = {
  runs: 'Most tested games run',
  mixed: 'Mixed',
  poor: 'Most tested games do not run reliably',
}

export interface Summary {
  judged: number
  ok: number // Great + Works
  great: number
  works: number
  unreliable: number
  broken: number
  okShare: number
  band: Band
}

export function summarize(states: States): Summary {
  const judged = states.great + states.works + states.unreliable + states.broken
  const ok = states.great + states.works
  const okShare = judged ? ok / judged : 0
  const band: Band =
    okShare >= BAND_MOSTLY_RUNS_MIN_SHARE
      ? 'runs'
      : okShare >= BAND_MIXED_MIN_SHARE
        ? 'mixed'
        : 'poor'
  return { judged, ok, ...states, okShare, band }
}

export function sumStates(list: States[]): States {
  const out: States = { great: 0, works: 0, unreliable: 0, broken: 0 }
  for (const s of list) {
    out.great += s.great
    out.works += s.works
    out.unreliable += s.unreliable
    out.broken += s.broken
  }
  return out
}

/* ──────────────────────────────────────────────────────────────────────────
 * Formatting
 * ────────────────────────────────────────────────────────────────────────── */

export function fmt(n: number): string {
  return n.toLocaleString('en-US')
}

/** "1 game", "3 games". */
export function count(n: number, singular: string, plural = `${singular}s`): string {
  return `${fmt(n)} ${n === 1 ? singular : plural}`
}

export function pct(share: number): string {
  if (share > 0 && share < 0.005) return '<1%'
  if (share < 1 && share > 0.995) return '>99%'
  return `${Math.round(share * 100)}%`
}

export function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC',
  })
}

/* ──────────────────────────────────────────────────────────────────────────
 * Per-game view (data/compat-games.json): the same verdicts, one row per
 * device / GPU, for games with enough devices to get their own page.
 * ────────────────────────────────────────────────────────────────────────── */

/** [entityIndex (into snapshot.devices / snapshot.gpus), state, sessions, playableSessions, medianFps] */
export type EntityRow = [number, StateCode, number, number, number | null]

export interface GamePage {
  /** Index into snapshot.games. */
  g: number
  slug: string
  /** Devices, most sessions first. */
  d: EntityRow[]
  /** GPUs, most sessions first. */
  p: EntityRow[]
}

const GAMES_PATH = path.join(process.cwd(), 'data', 'compat-games.json')
let gamePages: GamePage[] | null = null
let gamePageBySlug: Map<string, GamePage> | null = null
let gamePageByIndex: Map<number, GamePage> | null = null

export function getGamePages(): GamePage[] {
  if (gamePages) return gamePages
  if (!fs.existsSync(GAMES_PATH)) {
    throw new Error(
      'data/compat-games.json is missing. Generate it with scripts/build-will-it-run-data.mjs before building.',
    )
  }
  gamePages = (JSON.parse(fs.readFileSync(GAMES_PATH, 'utf8')) as { games: GamePage[] }).games
  return gamePages
}
export function getGamePage(slug: string): GamePage | undefined {
  gamePageBySlug ??= new Map(getGamePages().map((g) => [g.slug, g]))
  return gamePageBySlug.get(slug)
}
export function gamePath(slug: string): string {
  return `/will-it-run/game/${slug}/`
}
/** Path of the game's own page, given its index into snapshot.games, or null when it has none. */
export function gamePathIfExists(gameIndex: number): string | null {
  gamePageByIndex ??= new Map(getGamePages().map((g) => [g.g, g]))
  const page = gamePageByIndex.get(gameIndex)
  return page ? gamePath(page.slug) : null
}

export function statesOf(rows: EntityRow[]): States {
  const out: States = { great: 0, works: 0, unreliable: 0, broken: 0 }
  for (const r of rows) {
    if (r[1] === 'G') out.great++
    else if (r[1] === 'W') out.works++
    else if (r[1] === 'U') out.unreliable++
    else out.broken++
  }
  return out
}

/* ──────────────────────────────────────────────────────────────────────────
 * Game-on-device pages ("Will Hollow Knight run on the Pixel 7?").
 * Only pairs with plenty of sessions get one; the rest stay rows on the game page.
 * ────────────────────────────────────────────────────────────────────────── */

/** A game/device pair needs at least this many sessions to get its own page. */
export const MIN_SESSIONS_FOR_PAIR_PAGE = 100

export function hasPairPage(row: EntityRow): boolean {
  return row[2] >= MIN_SESSIONS_FOR_PAIR_PAGE && hasPage(getSnapshot().devices[row[0]])
}
export function pairPath(gameSlug: string, deviceSlug: string): string {
  return `/will-it-run/game/${gameSlug}/${deviceSlug}/`
}
export function getPairParams(): { slug: string; device: string }[] {
  const devices = getSnapshot().devices
  return getGamePages().flatMap((g) =>
    g.d.filter(hasPairPage).map((r) => ({ slug: g.slug, device: devices[r[0]].slug })),
  )
}
export function getPair(gameSlug: string, deviceSlug: string) {
  const page = getGamePage(gameSlug)
  const devices = getSnapshot().devices
  const row = page?.d.find((r) => devices[r[0]].slug === deviceSlug)
  return page && row && hasPairPage(row) ? { page, row, device: devices[row[0]] } : undefined
}
/** Pair page for a game (index into snapshot.games) on a device (index into snapshot.devices), or null. */
export function pairPathIfExists(gameIndex: number, deviceIndex: number): string | null {
  gamePageByIndex ??= new Map(getGamePages().map((g) => [g.g, g]))
  const page = gamePageByIndex.get(gameIndex)
  const row = page?.d.find((r) => r[0] === deviceIndex)
  return page && row && hasPairPage(row)
    ? pairPath(page.slug, getSnapshot().devices[deviceIndex].slug)
    : null
}
